{"path": "creative_intent.json", "content": "{
  "x_axis_mode": {
    "id": "F31",
    "name": "悔恨 (Remorse)",
    "description": "犯罪者在罪行后良心折磨，自我救赎"
  },
  "y_axis_tags": [
    {
      "id": "Y7",
      "name": "重生/穿越",
      "description": "主角掌握未来信息，回到过去改变命运"
    },
    {
      "id": "Y1",
      "name": "双向暗恋",
      "description": "双方互生情愫但未捅破，制造甜蜜错位"
    }
  ],
  "reaction_strength": "↗",
  "emotional_tone": "sweet",
  "genre": ["竞技", "心理悬疑", "甜宠"],
  "word_count_target": 150000,
  "core_premise": "体操教练重生回运动员时期，发现前世被她'无意'推下平衡木的队友其实当时是为保护她（道具故障）。这一世她拼命补偿，却发现队友也重生了，且对她的'好意'充满恐惧——在队友的时间线里，她是故意推人的。但真相很快揭开：两人都记错了，事故是道具故障。赎罪变撒糖，复仇变宠溺，两人在赛场互相成就，最终夺冠+相爱。",
  "key_sweet_points": [
    "第一章结尾就揭开事故真相，避免压抑",
    "女主的'赎罪'变成'找借口接近你'",
    "男主的'复仇'变成'看你这次怎么补偿我'（宠溺式）",
    "真相揭开后变成调情素材",
    "赛场互相成就+日常撒糖",
    "打脸前世质疑者，夺冠爽感"
  ],
  "prohibited_elements": [
    "长期误会不解释",
    "过度虐心情节",
    "主角能力崩坏",
    "逻辑前后矛盾"
  ]
}
"}

